  assert.deepEqual(a.assign(0), [{ start: 0, end: 1000 }]);
  assert.deepEqual(a.assign(999), [{ start: 0, end: 1000 }]);
  assert.deepEqual(a.assign(1000), [{ start: 1000, end: 2000 }]);
  assert.deepEqual(a.assign(2500), [{ start: 2000, end: 3000 }]);
});

