  1	/**
  2	 * Event-time watermark tracker.
  3	 * A watermark means the tracker believes no event with an event time before
  4	 * that point should arrive any more (apart from allowed late events).
  5	 */
  6	export class WatermarkTracker {
  7	  constructor({ allowedLatenessMs = 0 } = {}) {
  8	    if (!Number.isFinite(allowedLatenessMs) || allowedLatenessMs < 0) {
  9	      throw new TypeError('allowedLatenessMs must be a non-negative finite number');
 10	    }
 11	
 12	    this.allowedLatenessMs = allowedLatenessMs;
 13	    this._maxEventTime = Number.NEGATIVE_INFINITY;
 14	    this._wm = Number.NEGATIVE_INFINITY;
 15	  }
 16	
 17	  observe(eventTimeMs) {
 18	    if (!Number.isFinite(eventTimeMs)) {
 19	      throw new TypeError('eventTimeMs must be a finite number');
 20	    }
 21	
 22	    this._maxEventTime = Math.max(this._maxEventTime, eventTimeMs);
 23	    this._wm = this._maxEventTime - this.allowedLatenessMs;
 24	    return this._wm;
 25	  }
 26	
 27	  current() {
 28	    return this._wm;
 29	  }
 30	}
  1	/**
  2	 * Window assigners and aggregation helpers.
  3	 * Window intervals use the event-time convention [start, end).
  4	 */
  5	
  6	function requirePositiveFinite(value, name) {
  7	  if (!Number.isFinite(value) || value <= 0) {
  8	    throw new TypeError(`${name} must be a positive finite number`);
  9	  }
 10	}
 11	
 12	export class TumblingWindowAssigner {
 13	  constructor({ sizeMs }) {
 14	    requirePositiveFinite(sizeMs, 'sizeMs');
 15	    this.sizeMs = sizeMs;
 16	  }
 17	
 18	  assign(eventTimeMs) {
 19	    if (!Number.isFinite(eventTimeMs)) {
 20	      throw new TypeError('eventTimeMs must be a finite number');
 21	    }
 22	
 23	    const start = Math.floor(eventTimeMs / this.sizeMs) * this.sizeMs;
 24	    return [{ start, end: start + this.sizeMs }];
 25	  }
 26	}
 27	
 28	export class SlidingWindowAssigner {
 29	  constructor({ sizeMs, slideMs }) {
 30	    requirePositiveFinite(sizeMs, 'sizeMs');
 31	    requirePositiveFinite(slideMs, 'slideMs');
 32	    this.sizeMs = sizeMs;
 33	    this.slideMs = slideMs;
 34	  }
 35	
 36	  assign(eventTimeMs) {
 37	    if (!Number.isFinite(eventTimeMs)) {
 38	      throw new TypeError('eventTimeMs must be a finite number');
 39	    }
 40	
 41	    const bucketStart = Math.floor(eventTimeMs / this.slideMs) * this.slideMs;
 42	    const windows = [];
 43	
 44	    if (this.sizeMs <= this.slideMs) {
 45	      windows.push({ start: bucketStart, end: bucketStart + this.sizeMs });
 46	      return windows;
 47	    }
 48	
 49	    const firstStart = bucketStart - this.sizeMs + this.slideMs;
 50	    for (let start = firstStart; start < bucketStart; start += this.slideMs) {
 51	      windows.push({ start, end: start + this.sizeMs });
 52	    }
 53	
 54	    return windows;
 55	  }
 56	}
 57	
 58	export function aggregateRecords(records) {
 59	  const count = records.length;
 60	  const sum = records.reduce((total, record) => total + record.value, 0);
 61	  return {
 62	    count,
 63	    sum,
 64	    avg: count === 0 ? 0 : sum / count,
 65	  };
 66	}
  1	/**
  2	 * Stream engine: event-time processing with watermark-driven window close.
  3	 */
  4	import { WatermarkTracker } from './watermark.js';
  5	import { aggregateRecords } from './window.js';
  6	
  7	export class StreamEngine {
  8	  constructor({ assigner, allowedLatenessMs = 0 } = {}) {
  9	    if (!assigner || typeof assigner.assign !== 'function') {
 10	      throw new TypeError('assigner must implement assign(eventTimeMs)');
 11	    }
 12	
 13	    this.assigner = assigner;
 14	    this.allowedLatenessMs = allowedLatenessMs;
 15	    this.wm = new WatermarkTracker({ allowedLatenessMs });
 16	    this.lateCount = 0;
 17	    this.lateEvents = [];
 18	    this.closedCount = 0;
 19	    this.results = [];
 20	    this._buffers = new Map(); // key|start|end -> window state
 21	    this._closed = new Set();
 22	    this._listeners = [];
 23	  }
 24	
 25	  onWindowClosed(fn) {
 26	    if (typeof fn !== 'function') {
 27	      throw new TypeError('onWindowClosed expects a function');
 28	    }
 29	    this._listeners.push(fn);
 30	  }
 31	
 32	  accept(event) {
 33	    if (!event || typeof event !== 'object') {
 34	      throw new TypeError('event must be an object');
 35	    }
 36	    if (!Number.isFinite(event.ts)) {
 37	      throw new TypeError('event.ts must be a finite number');
 38	    }
 39	
 40	    const windows = this.assigner.assign(event.ts);
 41	    const isWatermarkLate = event.ts < this.wm.current();
 42	    const touchesClosedWindow = windows.some((window) =>
 43	      this._closed.has(this._windowId(event.key, window)));
 44	
 45	    if (isWatermarkLate || touchesClosedWindow) {
 46	      this.lateCount += 1;
 47	      this.lateEvents.push(event);
 48	      return false;
 49	    }
 50	
 51	    for (const window of windows) {
 52	      const id = this._windowId(event.key, window);
 53	      if (!this._buffers.has(id)) {
 54	        this._buffers.set(id, {
 55	          key: event.key,
 56	          start: window.start,
 57	          end: window.end,
 58	          records: [],
 59	        });
 60	      }
 61	      this._buffers.get(id).records.push(event);
 62	    }
 63	
 64	    this.wm.observe(event.ts);
 65	    this._closeDueWindows();
 66	    return true;
 67	  }
 68	
 69	  flush() {
 70	    this._closeDueWindows({ closeAll: true });
 71	    return [...this.results];
 72	  }
 73	
 74	  _windowId(key, window) {
 75	    return `${String(key)}\u0000${window.start}\u0000${window.end}`;
 76	  }
 77	
 78	  _closeDueWindows({ closeAll = false } = {}) {
 79	    const watermark = this.wm.current();
 80	    const due = [...this._buffers.values()]
 81	      .filter((state) => closeAll || state.end <= watermark)
 82	      .sort((a, b) => a.end - b.end || a.start - b.start || String(a.key).localeCompare(String(b.key)));
 83	
 84	    for (const state of due) {
 85	      const id = this._windowId(state.key, state);
 86	      if (this._closed.has(id)) {
 87	        continue;
 88	      }
 89	
 90	      const result = {
 91	        key: state.key,
 92	        start: state.start,
 93	        end: state.end,
 94	        ...aggregateRecords(state.records),
 95	      };
 96	
 97	      this._closed.add(id);
 98	      this._buffers.delete(id);
 99	      this.results.push(result);
100	      this.closedCount += 1;
101	      for (const listener of this._listeners) {
102	        listener(result);
103	      }
104	    }
105	  }
106	}
