  9	export function parseJsonl(text) {
 10	  return text
 11	    .split(/\r?\n/)
 12	    .map((line, index) => {
 13	      const trimmed = line.trim();
 14	      if (!trimmed) return null;
 15	
 16	      try {
 17	        const event = JSON.parse(trimmed);
 18	        if (!event || typeof event !== 'object') {
 19	          throw new Error('event must be a JSON object');
 20	        }
 21	        if (event.key === undefined || event.key === null) {
 22	          throw new Error('event.key is required');
 23	        }
 24	        if (!Number.isFinite(event.ts)) {
 25	          throw new Error('event.ts must be a finite number');
 26	        }
 27	        if (!Number.isFinite(event.value)) {
 28	          throw new Error('event.value must be a finite number');
 29	        }
 30	        return event;
 31	      } catch (error) {
 32	        throw new Error(`Invalid JSONL on line ${index + 1}: ${error.message}`);
 33	      }
 34	    })
 35	    .filter(Boolean);
 36	}
