 42	function readConfig(opts) {
 43	  const sizeMs = Number(element('sizeMs', opts.sizeInput)?.value);
 44	  const slideMs = Number(element('slideMs', opts.slideInput)?.value);
 45	  const allowedLatenessMs = Number(element('latenessMs', opts.latenessInput)?.value);
 46	  const assignerType = element('assigner', opts.assignerInput)?.value || 'tumbling';
 47	
 48	  if (!Number.isFinite(sizeMs) || sizeMs <= 0) {
 49	    throw new Error('Window size must be a positive number.');
 50	  }
 51	  if (!Number.isFinite(slideMs) || slideMs <= 0) {
 52	    throw new Error('Sliding step must be a positive number.');
 53	  }
 54	  if (!Number.isFinite(allowedLatenessMs) || allowedLatenessMs < 0) {
 55	    throw new Error('Allowed lateness must be a non-negative number.');
 56	  }
 57	
 58	  const assigner = assignerType === 'sliding'
 59	    ? new SlidingWindowAssigner({ sizeMs, slideMs })
 60	    : new TumblingWindowAssigner({ sizeMs });
 61	
 62	  return { sizeMs, slideMs, allowedLatenessMs, assigner };
 63	}
 64	
